// Prepended to each worker setup body by scripts/build-advanced-plugins.mjs.
// No runtime imports or external dependencies. Each JSON is self-contained.
const h = ctx.h;
const text = value => String(value == null ? '' : value);
const tagsOf = card => Array.isArray(card.tags) ? card.tags : [];
const includes = (value, query) => text(value).toLowerCase().includes(text(query).toLowerCase());
const number = (value, fallback, min, max) => Number.isFinite(Number(value))
  ? Math.max(min, Math.min(max, Number(value))) : fallback;
let panel = null;
let queue = Promise.resolve();
let notice = '';
let draw = async () => [];
let heading = '';
let refreshButton;
const action = fn => (...args) => {
  queue = queue.then(() => fn(...args)).catch(async error => {
    notice = text(error.message || error);
    await ctx.api.ui.showToast(notice, 'error');
  });
  return queue;
};
const button = (label, fn, disabled = false) => h('button', {
  type: 'button', className: 'btn', disabled, onclick: action(fn)
}, label);
const field = (label, value, change, type = 'text') => h('label', { className: 'lab-field' }, [
  h('span', {}, label), h(type === 'textarea' ? 'textarea' : 'input', {
    type: type === 'textarea' ? undefined : type, value,
    'aria-label': label, oninput: event => { change(event.target.value); }
  }, type === 'textarea' ? value : undefined)
]);
const select = (label, value, choices, change) => h('label', { className: 'lab-field' }, [
  h('span', {}, label), h('select', { 'aria-label': label, onchange: event => { change(event.target.value); } },
    choices.map(([id, name]) => h('option', { value: id, selected: id === value }, name)))
]);
const box = children => h('div', { className: 'lab-box' }, children);
const row = children => h('div', { className: 'lab-row' }, children);
const title = card => card.title || '(Untitled)';
async function paint() {
  if (!panel) return;
  const children = await draw();
  await panel.update(h('section', { className: 'cs-lab', id: ctx.modId + '-panel', 'aria-label': heading }, [
    row([h('h2', {}, heading), button('Refresh', async () => { notice = ''; await paint(); }),
      button('Close', async () => { await panel.remove(); panel = null; })]),
    h('p', { role: 'status', className: 'lab-notice' }, notice), ...children
  ]));
}
async function start(label, render) {
  heading = label;
  draw = render;
  refreshButton = await ctx.api.ui.inject('.header', button(label, async () => {
    if (!panel) panel = await ctx.api.ui.inject('#main', h('section', {}), 'before');
    await paint();
  }), 'append');
  // Notify without replacing a form while someone is typing. Refresh is explicit.
  ctx.api.data.onUpdate(() => { notice = 'Cards changed. Refresh to see the latest data.'; });
}
async function readState(key, fallback) {
  const stored = await ctx.api.storage.get(key);
  return stored && stored.schema === 1 ? stored.value : fallback;
}
const writeState = (key, value) => ctx.api.storage.set(key, { schema: 1, value });
const cardSignature = card => JSON.stringify([card.title, card.body, tagsOf(card), card.parentId]);

let query = '', tag = '', prefix = '', preview = [];
// History is session-local: card IDs can overlap across datasets. A reload
// deliberately discards undo instead of applying it to an unrelated dataset.
let history = [];
await start('Batch Workbench', async () => [
  h('p', {}, 'Preview matching cards, apply title prefixes and tags, then undo only cards unchanged since this batch. Maximum 100 cards; undo is available until reload or suspend.'),
  row([field('Title contains', query, value => { query = value; }),
    field('Add tag', tag, value => { tag = value; }), field('Title prefix', prefix, value => { prefix = value; })]),
  row([button('Preview changes', async () => {
    if (!tag.trim() && !prefix) throw new Error('Enter a tag or title prefix.');
    const cards = (await ctx.api.data.listCards()).filter(card => includes(card.title, query));
    if (cards.length > 100) throw new Error('More than 100 matches. Narrow the title filter.');
    preview = cards.map(card => ({ id: card.id, before: cardSignature(card), oldTitle: card.title,
      oldTags: tagsOf(card), title: prefix + card.title,
      tags: [...new Set([...tagsOf(card), ...tag.toLowerCase().split(',').map(t => t.trim()).filter(Boolean)])] }));
    notice = preview.length + ' changes ready. Review below.'; await paint();
  }), button('Apply preview', async () => {
    if (!preview.length) throw new Error('Preview changes first.');
    const candidates = preview;
    preview = []; history = [];
    let skipped = 0;
    for (const item of candidates) {
      const current = await ctx.api.data.getCard(item.id);
      if (!current || cardSignature(current) !== item.before) { skipped++; continue; }
      const updated = await ctx.api.data.updateCard(item.id, { title: item.title, tags: item.tags });
      if (!updated || updated.title !== item.title || JSON.stringify(tagsOf(updated)) !== JSON.stringify(item.tags))
        throw new Error('Card update did not complete; previous changes can be undone.');
      history.push({ ...item, after: cardSignature(updated) });
    }
    notice = history.length + ' updated; ' + skipped + ' changed cards skipped.'; await paint();
  }), button('Undo last batch', async () => {
    let restored = 0, skipped = 0;
    const remaining = [];
    for (const item of history) {
      const current = await ctx.api.data.getCard(item.id);
      if (!current || cardSignature(current) !== item.after) { skipped++; remaining.push(item); continue; }
      await ctx.api.data.updateCard(item.id, { title: item.oldTitle, tags: item.oldTags }); restored++;
    }
    history = remaining; notice = restored + ' restored; ' + skipped + ' changed cards skipped.'; await paint();
  }, !history.length)]),
  ...preview.map(item => box([h('strong', {}, item.oldTitle + ' → ' + item.title), h('p', {}, item.tags.join(', '))]))
]);
